-- -----------------------------------------------------------------------------
-- One-time setup: give the Azure DevOps pipeline identity access to deploy
-- the database project '{{ProjectName}}'.
-- Generated by SQL Database Project Power Tools
--
-- Guide: {{DocsUrl}}#passwordless-access-to-azure-sql
--
-- Run this script ONCE in EACH target user database (not in master).
{{ConnectAs}}
-- -----------------------------------------------------------------------------

{{CreateUser}}

-- db_owner is NOT required. These permissions cover typical schema deployments:
ALTER ROLE db_ddladmin ADD MEMBER [{{UserName}}];   -- create, alter and drop schema objects
ALTER ROLE db_datareader ADD MEMBER [{{UserName}}]; -- SqlPackage reads data when it rebuilds tables
ALTER ROLE db_datawriter ADD MEMBER [{{UserName}}]; -- SqlPackage writes data when it rebuilds tables, and post-deployment scripts
GRANT VIEW DEFINITION TO [{{UserName}}];            -- read the current schema to compare with the .dacpac
GRANT EXECUTE TO [{{UserName}}];                    -- post-deployment scripts that call procedures or functions
GO

-- Only needed if the project itself contains users, roles or permissions:
-- ALTER ROLE db_securityadmin ADD MEMBER [{{UserName}}];
-- GRANT ALTER ANY USER TO [{{UserName}}];
-- GO
